allcounts=collections.Counter();initials={};checks=[]
for q in m['read']:
 p=pathlib.Path(q)
 if not p.name.endswith('-native.jsonl'):continue
 case=p.parent;role=p.name[:-13];nat=jl(p);proj=jl(case/f'{role}-tool-messages.jsonl');trace=jl(case/f'{role}-trace.jsonl');md=js(case/f'{role}-capture-metadata.json');integ=js(case/f'{role}-native-integrity.json');sett=js(case/f'{role}-settings.json');manifest=js(case/f'{role}-manifest.json');receipts=js(case/f'{role}-dispatch-receipts.json');prompt=data(case/f'{role}-prompt.txt');ledger=js(case/f'{role}-access-ledger.json');err=[]
