 dts=datetime.datetime.fromisoformat(receipts[0]['timestamp'].replace('Z','+00:00')).timestamp();pns=(case/f'{role}-prompt.txt').stat().st_mtime_ns
 if pns!=md['prompt_mtime_ns'] or pns/1e9>=dts:err.append('prompt timestamp mismatch')
 envp=case/f'{role}-submission.json';hasenv=str(envp) in allow
 if hasenv:
  env=js(envp)
  if env['message'].encode()!=prompt:err.append('envelope message mismatch')
  if {k:v for k,v in env.items() if k!='message'} != {k:v for k,v in args.items() if k!='message'}:err.append('envelope setting mismatch')
  if envp.stat().st_mtime_ns/1e9>=dts:err.append('envelope timestamp after dispatch')
 calls=[x for x in nat if x['type']=='response_item' and x['payload']['type'] in ['function_call','custom_tool_call']]
 expectedledger=[{'timestamp':x['timestamp'],'ordinal':x['ordinal'],'tool':x['payload']['name'],'input':x['payload'].get('input',x['payload'].get('arguments'))} for x in calls]
 if ledger!=expectedledger:err.append('ledger mismatch')
 last=[x for x in nat if x['type']=='response_item' and x['payload']['type']=='message' and x['payload'].get('phase')=='final']
 if len(last)!=1 or '\n'.join(texts(last[-1]['payload'])).strip()!=data(case/f'{role}-final.txt').decode().strip():err.append('final mismatch')
 if nat[-1]['payload'].get('type')!='task_complete':err.append('missing completion')
 tr=[];cmd_count=0;write_count=0;cats=[]
 for x in nat:
  z=x['payload'];o=x['ordinal']
  if x['type']=='response_item' and z['type'] in ['function_call_output','custom_tool_call_output'] and re.search(r'truncat|omitted',json.dumps(z),re.I):tr.append(o)
